const env = vars.env || undefined, svc = vars.service;
const consul = await tools.consul_service({ name: svc, env }).catch(e => ({ error: e.message }));
const logs = await tools.logs_search({ env, service: svc, level: 'ERROR', from: vars.window, size: 200 }).catch(e => ({ error: e.message }));
const lag = await tools.kafka_lag({ env, top: 200 }).catch(e => ({ error: e.message }));
const instances = (consul.instances || []).map(i => ({ node: i.node, status: i.status, version: i.meta?.version || i.version || null }));
const mine = (logs.preview || []).filter(l => !l.service || l.service === svc);
const byMessage = {};
for (const l of mine) { const k = String(l.message || '').replace(/\d+/g, 'N').slice(0, 160); byMessage[k] = (byMessage[k] || 0) + 1; }
const errors = Object.entries(byMessage).sort((a, b) => b[1] - a[1]).map(([message, count]) => ({ message, count }));
const groups = (lag.rows || []).filter(g => String(g.group).includes(svc)).map(g => ({ group: g.group, lag: g.lag, state: g.state }));
const errorCount = (logs.services || []).find(s => s.key === svc)?.count ?? mine.length;
const need = (r, what) => { if (r.error) throw new Error(`${what} unavailable: ${r.error}`); };
test('every instance is passing', () => { need(consul, 'Consul'); expect(instances.length > 0).toBe(true); expect(instances.filter(i => i.status !== 'passing').map(i => i.node)).toEqual([]); });
test(`no ERROR logs in the last ${vars.window}`, () => { need(logs, 'logs'); expect(errorCount).toBe(0); });
test(`consumer lag at most ${vars.maxLag}`, () => { need(lag, 'Kafka'); expect(groups.filter(g => g.lag > vars.maxLag).map(g => `${g.group}: ${g.lag}`)).toEqual([]); });
return { service: svc, versions: [...new Set(instances.map(i => i.version).filter(Boolean))], instances, errorCount, errors: errors.slice(0, 10), kibana: logs.kibana, lag: groups, unavailable: Object.entries({ consul, logs, lag }).filter(([, r]) => r.error).map(([k, r]) => `${k}: ${r.error}`) };
